package com.nigson.experience.careers;
import java.util.*;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;
class CareerSecretsTest {
 @Test void emailCiphertextIsRandomAuthenticatedAndLookupFingerprintIsStable(){byte[] aes=new byte[32],hmac=new byte[32];Arrays.fill(aes,(byte)3);Arrays.fill(hmac,(byte)8);var secrets=new CareerSecrets(1,hmac,"synthetic",Map.of("synthetic",aes));var id=java.util.UUID.randomUUID();byte[] first=secrets.encrypt(id,"person@example.invalid"),second=secrets.encrypt(id,"person@example.invalid");assertThat(first).isNotEqualTo(second);assertThat(secrets.decrypt(id,first)).isEqualTo("person@example.invalid");assertThat(secrets.fingerprint("Person@Example.Invalid")).isEqualTo(secrets.fingerprint("person@example.invalid"));String[] parts=new String(first,java.nio.charset.StandardCharsets.US_ASCII).split("\\.",-1);byte[] body=Base64.getUrlDecoder().decode(parts[3]);body[body.length-1]^=1;byte[] corrupt=(parts[0]+"."+parts[1]+"."+parts[2]+"."+Base64.getUrlEncoder().withoutPadding().encodeToString(body)).getBytes(java.nio.charset.StandardCharsets.US_ASCII);assertThatThrownBy(()->secrets.decrypt(id,corrupt)).isInstanceOf(IllegalStateException.class);}
 @Test void invalidOrMissingKeyMaterialFailsClosed(){assertThatThrownBy(()->new CareerSecrets(1,new byte[32],"missing",Map.of())).isInstanceOf(IllegalArgumentException.class);}
 @Test void uploadCapabilityIsHighEntropyPurposeAndSessionBoundAndEncryptedForReplay(){byte[] aes=new byte[32],hmac=new byte[32];Arrays.fill(aes,(byte)3);Arrays.fill(hmac,(byte)8);var secrets=new CareerSecrets(1,hmac,"synthetic",Map.of("synthetic",aes));var id=UUID.randomUUID();String token=secrets.uploadToken();assertThat(token).hasSize(43).matches("[A-Za-z0-9_-]{43}");byte[] encrypted=secrets.encryptUploadToken(id,token);assertThat(new String(encrypted,java.nio.charset.StandardCharsets.US_ASCII)).doesNotContain(token);assertThat(secrets.decryptUploadToken(id,encrypted)).isEqualTo(token);assertThatThrownBy(()->secrets.decryptUploadToken(UUID.randomUUID(),encrypted)).isInstanceOf(IllegalStateException.class);String[] parts=new String(encrypted,java.nio.charset.StandardCharsets.US_ASCII).split("\\.",-1);byte[] body=Base64.getUrlDecoder().decode(parts[4]);body[body.length-1]^=1;byte[] corrupt=(parts[0]+"."+parts[1]+"."+parts[2]+"."+parts[3]+"."+Base64.getUrlEncoder().withoutPadding().encodeToString(body)).getBytes(java.nio.charset.StandardCharsets.US_ASCII);assertThatThrownBy(()->secrets.decryptUploadToken(id,corrupt)).isInstanceOf(IllegalStateException.class);}
 @Test void localAntiSpamMockIsKeyBoundReplayableAndOneRequestScoped(){byte[] key=new byte[32];Arrays.fill(key,(byte)4);var mock=new LocalCareerAntiSpamMock(Base64.getEncoder().encodeToString(key));String nonce="synthetic-nonce-1234",idem="career-command-1",token=mock.sign(nonce,idem);assertThat(mock.verify(token,idem)).isTrue();assertThat(mock.verify(token,idem)).isTrue();assertThat(mock.verify(token,"career-command-2")).isFalse();assertThat(mock.verify("invalid",idem)).isFalse();}
}
